    static int depth = 0;
    static int step = 0;

    static void log(String line) {
        step++;
        System.out.println(step + "\t" + line + "\t" + depth);
    }

    static int mix(int n) {
        depth++;
        log("enter " + n);
        if (n <= 1) {
            log("return " + n);
            depth--;
            return n;
        }
        int left = mix(n - 1);
        int right = mix(n - 2);
        int result = left + right + 1;
        log("return " + result);
        depth--;
        return result;
    }

